"""Measured outcomes only;always preserve unsuccessful/incomplete outcomes."""
from native_common import *
def read(p):return json.loads((O/p).read_text()) if (O/p).exists() else {}
def save(n,title,data,explain=''): (O/n).write_text('# '+title+'\n\n'+explain+'\n\n```json\n'+json.dumps(data,indent=2)+'\n```\n')
training={m:read(f'arms/{m}/RESULT.json') for m in ['control','candidate']};eig=read('evaluation/EIG_RESULTS.json');spec=read('evaluation/SPECIALIZATION_RESULTS.json');done=read('evidence/EXPERIMENT_COMPLETION.json');latency=read('evaluation/INFERENCE_LATENCY.json')
save('TRAINING_RESULTS.md','Native training results',training,'Fresh native seed101,new independently seeded collaborative actor,emptyAdam/replay;fixed10001iterations. Native updates/simulator episodes and auxiliary calculations match,actual times reported. INCOMPLETE if either arm lacks COMPLETE status.')
save('EIG_COMPARISON.md','Full-horizon EIG',dict(results=eig,inference_latency=latency),'Finite-contrast prior-EIG lower-bound estimates,not exact EIG. Co-primary Holm2 with ordinary paired95%CI;common2000case/1Mcontrastbank. Frozen Option/vsOED references are not current-training-compute-matched. INCOMPLETE unless frozen evaluation completed.')
save('SPECIALIZATION_ANALYSIS.md','Useful feature specialization',spec,'Different representations or task accuracy alone do not establish useful design specialization. Require held-out transfer-probe task advantages,valid full-policy expert removal effects and history-routing gain beyond stage. No certified same-history posterior conditionalEIG;that unresolved diagnostic is not used. INCOMPLETE where absent.')
p=eig.get('paired',{});gains=[p.get(k,{}).get('mean',-1)>0 and p.get(k,{}).get('Holm_primary_p',1)<.05 for k in ['control','reference']];special=spec.get('specialization_criterion_met',False);complete=done.get('status')=='COMPLETE';category='BLOCKED' if not complete else 'SUCCESSFUL_CANDIDATE' if all(gains) and special else 'PARTIAL_SUCCESS' if any(gains) or special else 'UNSUCCESSFUL'
save('NEXT_RESEARCH_DECISION.md','Research decision',dict(category=category,co_primary_gains=gains,useful_specialization=special,completion=done,additional_candidates=False),'No training extension/additional candidate. Preserve negative results. Nonsignificance is not equality. This single-seed pilot cannot establish ICML novelty or compute-matched superiority over frozen baselines.')
save('RUN_INDEX.md','Collaborative soft MoE',dict(status=category,completion=done),'Scientific outputs isolated here. QUEUE_STATUS.json is live LabPC status;queue_logs/watcher.log is the durable dependency/launch log. Source/config/CPUchecks queuedlocked before startup;GPUinitialization and scientificpreservation locked after upstream completion. No Ubuntu access,final-test use,or existing-job interruption.')
